{
  "summary": "Depomed grants King a non-exclusive right to use Launch Promotional Materials, a royalty-free license to use and reproduce promotional material copyrights, a non-exclusive right and license to use Depomed Trademarks, and an exclusive option for a Combination Product License.",
  "evidence": [
    {
      "passage_id": 2,
      "quote": "Depomed hereby grants to King the non-exclusive right, during the Term, to use the Launch Promotional Materials supplied to King pursuant to this Section 4.4(c) in the performance of its obligations under this Agreement."
    },
    {
      "passage_id": 2,
      "quote": "Depomed shall, and does hereby, grant to King a royalty-free license to use and reproduce such materials solely in conjunction with its Promotion of the Product pursuant to this Agreement, which license shall not be assignable or transferable by Ki"
    },
    {
      "passage_id": 3,
      "quote": "Depomed hereby grants to King a non-assignable, non- sublicensable, non-exclusive, royalty-free right and license to use the Depomed Trademarks in the Territory solely in connection with King's Promotion of the Product in accordance with this Agreement"
    },
    {
      "passage_id": 4,
      "quote": "Depomed agrees to grant and hereby grants to King an exclusive option (exercisable at King's sole discretion by providing written notice of intent at any time, but in no event later than 180 days after the Effective Date) to obtain an exclusive license in the Territory to certain of Depomed's proprietary drug delivery technology in combination with both metformin hydrochloride and any other active pharmaceutical ingredients (a \"Combination Product License\")."
    }
  ]
